import openpyxl
import datetime

wb = openpyxl.load_workbook('testbed/data/order_summary.xlsx')
ws = wb.active

rows = list(ws.iter_rows(values_only=True))
if not rows:
    print("No data found in spreadsheet")
else:
    header = rows[0]
    print("COLUMNS:", list(header))
    print("TOTAL ROWS:", len(rows) - 1)
    print("---")
    for i, row in enumerate(rows[1:], 1):
        print(f"ROW {i}:", list(row))
    print("---")
    matches = []
    for row in rows[1:]:
        for cell in row:
            if cell is not None and 'ORD-5B048F' in str(cell):
                matches.append(row)
                break
    if matches:
        print()
        print("=== ORDER ORD-5B048F DETAILS ===")
        for m in matches:
            for h, v in zip(header, m):
                print(f"  {h}: {v}")
    else:
        print()
        print("ORD-5B048F not found in any row")
wb.close()
